-- V12 (advisor products): the fictional product catalogue of "Ngân hàng TMCP Lục Bình" (ADR-0027).
--
-- Reference data, not user data: 18 rows, the same for every user, read by the advisor tools listProducts and
-- getProductDetails. The bank, its fund company (Lục Bình Quản lý Quỹ) and the insurer (An Khuê) do not exist and every
-- figure is illustrative, as of the date in as_of (rates and fees derived from the market ranges of Nov 2026, not copied
-- from a real product). A table of typed columns for what the compact list shows and what the rules compare (risk
-- level, profiles, minimums), and text or JSON for the long customer text of a product sheet; 18 rows are not worth
-- normalising into several tables. The research and its sources are kept outside the repository.
--
-- suitable_profiles uses the three levels of the onboarding questionnaire (CONSERVATIVE, BALANCED, GROWTH; the research
-- called the last one AGGRESSIVE). risk_level is 1 to 5, the scale of the catalogue; risk_kind says what it measures: the
-- investment risk of a deposit or fund (INVESTMENT), the risk of over-indebtedness or high cost of a loan or card
-- (DEBT), or a protection product (PROTECTION). risk_level_max differs from risk_level where the risk depends on the
-- fund chosen (SIP) or on how the product is used (a card with a carried balance).

CREATE TABLE catalog_products (
    code                   TEXT        PRIMARY KEY,
    sort_order             INTEGER     NOT NULL,
    name                   TEXT        NOT NULL,
    product_group          TEXT        NOT NULL,
    category               TEXT        NOT NULL,
    risk_kind              TEXT        NOT NULL,
    risk_level             INTEGER     NOT NULL,
    risk_level_max         INTEGER     NOT NULL,
    suitable_profiles      JSONB       NOT NULL,   -- JSON array of CONSERVATIVE, BALANCED, GROWTH
    profile_note           TEXT,                   -- conditions on the profiles, e.g. "only as a small satellite"
    min_amount_vnd         BIGINT,
    min_amount_unit        TEXT,                   -- what the minimum is per: one time, month, year, instalment
    min_monthly_income_vnd BIGINT,
    headline               TEXT        NOT NULL,   -- headline rate or return, one line
    tenor                  TEXT        NOT NULL,
    liquidity              TEXT        NOT NULL,
    summary                TEXT        NOT NULL,   -- one line for the compact list
    description            TEXT        NOT NULL,
    figures                JSONB       NOT NULL,   -- JSON array of strings: rates, limits, fees, examples
    rate_table             JSONB,                  -- the term deposit's rates by tenor, online and counter
    eligibility            TEXT        NOT NULL,
    suits                  TEXT        NOT NULL,
    not_suits              TEXT        NOT NULL,
    cautions               JSONB       NOT NULL,   -- JSON array of strings the advisor must mention
    as_of                  DATE        NOT NULL,   -- the date the figures are as of
    illustrative           BOOLEAN     NOT NULL DEFAULT TRUE,
    CONSTRAINT ck_catalog_products_group CHECK (product_group IN ('DEPOSIT', 'FUND', 'LOAN', 'CARD', 'INSURANCE')),
    CONSTRAINT ck_catalog_products_kind CHECK (risk_kind IN ('INVESTMENT', 'DEBT', 'PROTECTION')),
    CONSTRAINT ck_catalog_products_risk CHECK (
        risk_level BETWEEN 1 AND 5 AND risk_level_max BETWEEN risk_level AND 5),
    CONSTRAINT ck_catalog_products_profiles CHECK (jsonb_typeof(suitable_profiles) = 'array')
);

INSERT INTO catalog_products (
    code, sort_order, name, product_group, category, risk_kind, risk_level, risk_level_max, suitable_profiles,
    profile_note, min_amount_vnd, min_amount_unit, min_monthly_income_vnd, headline, tenor, liquidity, summary,
    description, figures, rate_table, eligibility, suits, not_suits, cautions, as_of, illustrative)
VALUES
($q$LBB-TD-ONL$q$, 1, $q$Tiết kiệm Lục Bình Trực tuyến$q$, $q$DEPOSIT$q$, $q$DEPOSIT_TERM$q$, $q$INVESTMENT$q$, 1, 1, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, NULL, 1000000, $q$một lần$q$, NULL, $q$4,50 đến 6,60%/năm tùy kỳ hạn 1 đến 24 tháng (online, trả lãi cuối kỳ); dưới 6 tháng trần 4,75%$q$, $q$1 đến 24 tháng$q$, $q$Medium. Money is available the same day on request but at the demand rate (0,10%), so withdrawing early forfeits nearly all interest. Practical rule: money that may be needed within the term should be in LBB-SAV-FLEX or LBB-CA-DEMAND instead.$q$, $q$Gửi có kỳ hạn mở trên ứng dụng, lãi cố định; rút trước hạn chỉ hưởng 0,10%/năm. Nền tảng cho mục tiêu 1 đến 24 tháng.$q$, $q$Tiết kiệm Lục Bình Trực tuyến là khoản tiền gửi có kỳ hạn mở hoàn toàn trên ứng dụng hoặc website, từ 1 đến 24 tháng, lãi suất cố định trong suốt kỳ hạn và được ghi rõ ngay khi gửi. Khách hàng có thể chọn nhận lãi cuối kỳ, hằng tháng hoặc nhập gốc, và chọn tự động tái tục gốc khi đến hạn. Tiền gửi thuộc phạm vi bảo hiểm tiền gửi theo quy định, tối đa 350 triệu đồng một người tại một tổ chức tín dụng, gồm cả gốc và lãi.$q$, $q$ ["Lãi suất theo kỳ hạn: xem rateTable (online và tại quầy, %/năm, trả lãi cuối kỳ, cố định suốt kỳ hạn).", "Interest paid monthly instead of at maturity: rate 0.20 point lower (not offered for 1 and 3 months).", "Kỳ hạn dưới 6 tháng: lãi suất không vượt trần 4,75%/năm theo quy định của Ngân hàng Nhà nước.", "Minimum: 1.000.000 VND online; 1.000.000 VND at the counter. No maximum.", "Fees: free to open, free to settle at maturity.", "Early withdrawal: the withdrawn amount earns the bank's lowest demand rate (0,10%/năm), not the term rate. Example: 100.000.000 VND for 12 months at 6,40% pays 6.400.000 VND of interest at maturity; withdrawn at month 6 it pays only about 50.000 VND (0,10%/năm for 6 months). Partial early withdrawal is allowed once per deposit: the withdrawn part earns 0,10%, the remaining part keeps the original rate if at least the minimum balance remains.", "At maturity, the principal rolls over for the same term at the then-current rate unless the customer chooses otherwise; interest is paid to the payment account.", "Pledge: the deposit can be used as collateral for a loan of up to 90% of the principal (the deposit rate keeps accruing)."]$q$::jsonb, $q$ {"unit": "%/năm, trả lãi cuối kỳ, cố định trong kỳ hạn; trả lãi hằng tháng thấp hơn 0,20 điểm (không áp dụng kỳ hạn 1 và 3 tháng)", "tenorMonths": [1, 3, 6, 9, 12, 13, 18, 24], "online": [4.5, 4.65, 5.9, 6.0, 6.4, 6.5, 6.5, 6.6], "counter": [4.2, 4.35, 5.6, 5.7, 6.1, 6.2, 6.2, 6.3]}$q$::jsonb, $q$Từ đủ 18 tuổi, công dân Việt Nam hoặc người nước ngoài cư trú hợp pháp, đã định danh điện tử (eKYC) hoặc có tài khoản thanh toán tại ngân hàng. Không yêu cầu thu nhập tối thiểu.$q$, $q$Phù hợp với mục tiêu có thời hạn rõ ràng từ 1 đến 24 tháng (quỹ đặt cọc, học phí kỳ sau, quỹ cưới, một phần quỹ khẩn cấp đã dự phòng riêng); người ưu tiên bảo toàn vốn; người đã có quỹ khẩn cấp ở nơi rút nhanh.$q$, $q$Không phù hợp để làm quỹ khẩn cấp duy nhất (rút trước hạn mất gần hết lãi); không phù hợp với tiền có thể phải dùng bất ngờ trong kỳ hạn (thu nhập không đều, đang nợ nhiều, chưa có quỹ dự phòng); không phù hợp với mục tiêu trên 5 năm nếu chỉ muốn bảo toàn sức mua, vì lãi suất tiền gửi có thể thấp hơn lạm phát và lợi suất dài hạn của quỹ.$q$, $q$ ["Rút trước hạn chỉ được hưởng lãi suất không kỳ hạn (0,10%/năm), gần như mất toàn bộ lãi.", "Lãi suất cố định theo kỳ hạn đã gửi; khi lãi suất thị trường tăng, khoản gửi cũ không được tăng lãi.", "Kỳ hạn 1 đến 5 tháng bị khống chế trần 4,75%; từ 6 tháng lãi suất cao hơn rõ rệt nhưng tiền bị khóa lâu hơn.", "Bảo hiểm tiền gửi chỉ chi trả tối đa 350 triệu đồng một người tại mỗi tổ chức tín dụng (gồm gốc và lãi); khoản gửi lớn hơn nên chia ra nhiều ngân hàng."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-CA-DEMAND$q$, 2, $q$Tài khoản thanh toán và Tiết kiệm không kỳ hạn Lục Bình$q$, $q$DEPOSIT$q$, $q$DEPOSIT_DEMAND$q$, $q$INVESTMENT$q$, 1, 1, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, NULL, 0, $q$tài khoản thanh toán; tiết kiệm không kỳ hạn từ 100.000$q$, NULL, $q$0,10%/năm (thanh toán), 0,30%/năm (tiết kiệm không kỳ hạn)$q$, $q$không kỳ hạn$q$, $q$Immediate, 24/7, no cost.$q$, $q$Nhận lương và chi tiêu hằng ngày, rút bất kỳ lúc nào; lãi rất thấp, chỉ giữ phần tiền cần dùng ngay (khoảng 1 tháng chi tiêu).$q$, $q$Tài khoản thanh toán dùng để nhận lương, chuyển khoản 24/7 và thanh toán hằng ngày; kèm tùy chọn tiết kiệm không kỳ hạn để giữ khoản tiền cần rút bất kỳ lúc nào. Lãi suất thấp nhưng tiền luôn sẵn sàng, không có phí duy trì khi dùng ứng dụng.$q$, $q$ ["Payment account interest: 0,10%/năm. Savings with no term: 0,30%/năm (below the 0,5% regulatory cap).", "Minimum: payment account 0 VND (no minimum balance); no-term savings 100.000 VND.", "Fees: account opening free; monthly maintenance free; domestic transfers through the app free; withdrawals at partner ATMs per tariff.", "Rate is applied to the daily balance, interest credited monthly."]$q$::jsonb, NULL, $q$Từ đủ 18 tuổi (16 đến dưới 18 tuổi cần người giám hộ), có CCCD gắn chip để định danh điện tử. Không yêu cầu thu nhập.$q$, $q$Nơi nhận lương và chi tiêu hằng ngày; phần đầu tiên của quỹ khẩn cấp (1 tháng chi tiêu); tiền chờ giải ngân vào mục tiêu ngắn hạn dưới 1 tháng.$q$, $q$Không nên để quá 1 đến 2 tháng chi tiêu trong tài khoản lãi 0,1 đến 0,3% khi lãi suất tiền gửi kỳ hạn cao hơn hẳn; không phải nơi tích lũy mục tiêu từ 6 tháng trở lên.$q$, $q$ ["Lãi suất rất thấp, thấp hơn lạm phát; chỉ nên giữ lượng tiền thật sự cần dùng ngay.", "Số dư thuộc phạm vi bảo hiểm tiền gửi tối đa 350 triệu đồng mỗi người tại mỗi ngân hàng.", "Tiền để lâu không giao dịch có thể bị phân loại tài khoản không hoạt động theo quy định của ngân hàng."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-SAV-FLEX$q$, 3, $q$Tiết kiệm Linh hoạt Lục Bình$q$, $q$DEPOSIT$q$, $q$DEPOSIT_FLEX$q$, $q$INVESTMENT$q$, 1, 1, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, NULL, 5000000, $q$một lần$q$, NULL, $q$4,30 đến 6,20%/năm (kỳ hạn 1 đến 12 tháng); rút một phần gốc, phần còn lại giữ lãi$q$, $q$1 đến 12 tháng$q$, $q$High. Any part of the principal can be withdrawn the same day; the cost is the interest lost on the withdrawn part only (the advisor should show this as: withdrawing 30% costs about 30% of the interest, not 100%).$q$, $q$Gửi kỳ hạn nhưng rút được từng phần gốc mà không mất lãi phần còn lại; hợp quỹ khẩn cấp 3 đến 6 tháng chi tiêu.$q$, $q$Tiền gửi có kỳ hạn nhưng cho phép rút một phần gốc trước hạn mà không làm mất lãi của phần còn lại. Phần rút ra chỉ hưởng lãi không kỳ hạn; phần giữ lại vẫn hưởng lãi suất đã chọn cho đến hết kỳ hạn. Phù hợp để giữ quỹ dự phòng sinh lời cao hơn tài khoản thanh toán mà vẫn lấy ra được khi cần.$q$, $q$ ["Interest, VND/year (online, at maturity): 1 tháng 4,30; 3 tháng 4,45; 6 tháng 5,70; 12 tháng 6,20 (0.20 below LBB-TD-ONL).", "Minimum: 5.000.000 VND to open; minimum balance after any partial withdrawal 2.000.000 VND.", "Partial withdrawal: unlimited number of times, any amount in multiples of 100.000 VND; the withdrawn part earns 0,10%/năm (the bank's lowest demand rate) for the period held; the remaining balance keeps the agreed rate to maturity.", "No top-up during the term (use LBB-SAV-ACCUM for regular saving).", "Fees: none. Full early closing pays the demand rate on the whole balance."]$q$::jsonb, NULL, $q$Từ đủ 18 tuổi, có tài khoản thanh toán Lục Bình. Không yêu cầu thu nhập.$q$, $q$Quỹ khẩn cấp (3 đến 6 tháng chi tiêu) khi người dùng muốn lãi tốt hơn tài khoản thanh toán; người thu nhập không đều (làm tự do, hoa hồng); người chưa chắc thời điểm cần tiền; quỹ dự phòng sửa nhà, y tế.$q$, $q$Người đã chắc chắn không động đến tiền trong 12 đến 24 tháng, vì tiết kiệm kỳ hạn LBB-TD-ONL trả lãi cao hơn khoảng 0,2 điểm phần trăm; người cần gửi thêm đều đặn (nên dùng tiết kiệm tích lũy).$q$, $q$ ["Lãi suất thấp hơn tiết kiệm kỳ hạn cùng thời hạn khoảng 0,20 điểm phần trăm; đây là chi phí của sự linh hoạt.", "Phần rút trước hạn chỉ hưởng lãi không kỳ hạn; rút hết trước hạn thì mất lãi của cả khoản.", "Số dư tối thiểu sau khi rút là 2.000.000 đồng; dưới mức này khoản gửi bị tất toán."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-SAV-ACCUM$q$, 4, $q$Tiết kiệm Góp Đều Lục Bình$q$, $q$DEPOSIT$q$, $q$SAVINGS_ACCUMULATING$q$, $q$INVESTMENT$q$, 1, 1, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, NULL, 100000, $q$mỗi lần góp$q$, NULL, $q$5,80 đến 6,60%/năm (kỳ hạn 6 đến 36 tháng); góp thêm hằng tháng$q$, $q$6 đến 36 tháng$q$, $q$Medium. Available any time but at the demand rate; the saver loses the interest accrued on the withdrawn instalments.$q$, $q$Tự động trích hằng tháng vào một sổ, từ 100.000 đồng; hợp mục tiêu 6 đến 36 tháng cho người có thu nhập đều.$q$, $q$Tiết kiệm tích lũy cho phép gửi thêm hằng tháng (hoặc bất kỳ lúc nào) vào cùng một sổ, từ 100.000 đồng mỗi lần. Hệ thống có thể tự động trích từ tài khoản thanh toán vào ngày chọn. Mỗi lần góp hưởng lãi suất theo thời gian còn lại của sổ, nên càng góp sớm càng hưởng lãi cao. Phù hợp để hình thành thói quen để dành cho mục tiêu từ 6 đến 36 tháng.$q$, $q$ ["Term 6 to 36 months. Interest, %/year, at maturity: 6 tháng 5,80; 12 tháng 6,30; 24 tháng 6,50; 36 tháng 6,60. Each instalment earns the rate for the remaining time, rounded down to the nearest bracket in this table; instalments with less than 1 month to run earn the demand rate. Rate is 0.10 point below the ordinary term table (market practice).", "Minimum per instalment: 100.000 VND; maximum per instalment 500.000.000 VND.", "Auto-debit: monthly on a chosen date; up to 3 consecutive missed instalments are allowed with no penalty; the saver can top up manually at any time.", "Early withdrawal: the principal still in the account earns the demand rate (0,10%); partial early withdrawal of the most recent instalments first is possible.", "Fees: none."]$q$::jsonb, NULL, $q$Từ đủ 18 tuổi, có tài khoản thanh toán Lục Bình để trích tự động. Không yêu cầu thu nhập tối thiểu.$q$, $q$Người có thu nhập đều muốn tự động để dành mỗi tháng cho mục tiêu như quỹ du lịch, đặt cọc xe, học phí; người mới bắt đầu tiết kiệm, ngưỡng thấp 100.000 đồng; thay thế cho thói quen "còn dư mới gửi".$q$, $q$Người thu nhập rất bấp bênh đang không có quỹ khẩn cấp (nên giữ tiền ở dạng rút nhanh trước); mục tiêu trên 5 năm cần tăng trưởng (nên dùng quỹ qua SIP); người có khoản nợ lãi cao đang trả (nên ưu tiên trả nợ).$q$, $q$ ["Rút trước hạn chỉ hưởng lãi không kỳ hạn trên phần rút.", "Lãi suất mỗi lần góp được xác định theo thời gian còn lại của sổ, lần góp muộn nhận lãi thấp hơn lần góp đầu.", "Bỏ lỡ quá 3 kỳ liên tiếp, hệ thống ngừng trích tự động; khoản đã góp vẫn được giữ đến hạn.", "Lãi suất cố định, không điều chỉnh theo thị trường sau khi mở sổ."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-CD-RETAIL$q$, 5, $q$Chứng chỉ tiền gửi Lục Bình$q$, $q$DEPOSIT$q$, $q$CERTIFICATE_OF_DEPOSIT$q$, $q$INVESTMENT$q$, 1, 1, $q$ ["CONSERVATIVE", "BALANCED"]$q$::jsonb, $q$Chỉ cho tiền nhàn rỗi chắc chắn không dùng trong kỳ hạn; không phải quỹ khẩn cấp.$q$, 20000000, $q$một lần$q$, NULL, $q$6,60 / 7,00 / 7,10%/năm (kỳ hạn 6 / 12 / 24 tháng); không rút trước hạn$q$, $q$6 đến 24 tháng$q$, $q$Low. Money cannot be taken out before maturity. A sale depends on finding a buyer or on pledging to borrow against it.$q$, $q$Giấy tờ có giá lãi cao hơn tiết kiệm nhưng không rút trước hạn và không phải tiền gửi; chỉ cho tiền nhàn rỗi.$q$, $q$Chứng chỉ tiền gửi là giấy tờ có giá do ngân hàng phát hành theo từng đợt, với kỳ hạn cố định và lãi suất cao hơn tiền gửi tiết kiệm cùng kỳ hạn. Chứng chỉ không được rút trước hạn; khách hàng có thể chuyển nhượng cho người khác hoặc cầm cố để vay. Phù hợp với khoản tiền nhàn rỗi chắc chắn không cần dùng trong kỳ hạn.$q$, $q$ ["Interest, %/year, at maturity (fixed): 6 tháng 6,60; 12 tháng 7,00; 24 tháng 7,10. About 0.6 to 0.7 point above the matching term-deposit rate (S7 shows CDs under 6 months at 6.5 to 8.5% at the large issuers, which are exempt from the 4.75% cap because the CD is a valuable paper, not a deposit).", "Denomination 10.000.000 VND; minimum purchase 20.000.000 VND (2 units); issued in batches (đợt) with a quota, so the product may be temporarily unavailable.", "No early redemption. Transfer to another person through the bank at a fee of 0,05% of face value (minimum 50.000 VND); pledge as collateral for a loan up to 90% of face value.", "Fees: no purchase fee."]$q$::jsonb, NULL, $q$Từ đủ 18 tuổi, có tài khoản thanh toán Lục Bình. Không yêu cầu thu nhập tối thiểu.$q$, $q$Người đã có quỹ khẩn cấp đầy đủ ở dạng rút nhanh, có khoản tiền nhàn rỗi 6 đến 24 tháng chắc chắn không dùng, muốn lãi cao hơn tiết kiệm thường; người thận trọng, không muốn rủi ro thị trường.$q$, $q$Không phù hợp với quỹ khẩn cấp; người thu nhập không đều; người đang có nợ lãi cao; người có thể cần tiền trong kỳ hạn (ví dụ có kế hoạch mua nhà hoặc xe trong 12 tháng tới chưa chốt ngày).$q$, $q$ ["Không được rút trước hạn; bán lại phụ thuộc người mua hoặc phải cầm cố vay vốn (có chi phí lãi vay).", "Chứng chỉ tiền gửi là giấy tờ có giá, không phải tiền gửi tiết kiệm; thông thường không thuộc phạm vi bảo hiểm tiền gửi (cần xác nhận theo điều khoản từng đợt phát hành).", "Rủi ro tín dụng của ngân hàng phát hành; lãi suất cao hơn thường do tính thanh khoản thấp.", "Không nhầm với trái phiếu doanh nghiệp; trái phiếu phát hành riêng lẻ chỉ dành cho nhà đầu tư chuyên nghiệp và không nằm trong danh mục này."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBF-LIQ$q$, 6, $q$Quỹ Lục Bình Thanh khoản (quỹ trái phiếu thanh khoản)$q$, $q$FUND$q$, $q$FUND_LIQUID$q$, $q$INVESTMENT$q$, 2, 2, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, NULL, 10000, $q$một lần$q$, NULL, $q$lịch sử 3,5 đến 5,5%/năm (không bảo đảm); bán hằng ngày, tiền về 1 đến 2 ngày làm việc$q$, $q$khuyến nghị 1 đến 12 tháng$q$, $q$High. Sell order any working day; the money arrives in about 1 to 2 working days; cost 0,10% if sold within 30 days, otherwise only the 0,1% tax.$q$, $q$Quỹ trái phiếu ngắn hạn, dao động rất nhỏ, bán hằng ngày; đệm thứ hai của quỹ khẩn cấp và mục tiêu dưới 12 tháng.$q$, $q$Quỹ mở đầu tư chủ yếu vào tiền gửi, chứng chỉ tiền gửi và trái phiếu ngắn hạn chất lượng tín dụng tốt, cho phép mua bán hằng ngày. Mục tiêu là lợi nhuận ổn định cao hơn lãi suất tiết kiệm ngắn hạn, với sự linh hoạt gần như tài khoản tiết kiệm. Giá trị chứng chỉ quỹ có thể dao động nhẹ và không được bảo đảm.$q$, $q$ ["Historical net return (not guaranteed): about 3,5 to 5,5%/năm over 3 to 5 years for comparable liquid bond funds; the fund targets a return above the average 3-month deposit rate of the large banks. Past performance does not guarantee future results; a negative month is possible but unusual.", "Recommended holding period: 1 to 12 months (as a place for money needed within the year).", "Minimum investment: 10.000 VND (first and further purchases).", "Fees: management fee 0,70%/năm (already in NAV); subscription fee 0%; redemption fee 0,10% if held 30 days or less, 0% after; no performance fee. Personal income tax on redemption proceeds 0,1% (withheld on the transfer value per fund practice).", "Dealing: every working day; cash in the payment account about 1 to 2 working days after the dealing day (estimate).", "Fund size and credit quality: invests at least 70% in deposits, CDs and bonds rated at or above the bank's internal investment grade; no equities."]$q$::jsonb, NULL, $q$Từ đủ 18 tuổi, có tài khoản thanh toán Lục Bình và đã hoàn thành bảng đánh giá khẩu vị rủi ro. Không yêu cầu thu nhập tối thiểu.$q$, $q$Phần "đệm" thứ hai của quỹ khẩn cấp sau tiết kiệm không kỳ hạn; tiền cho mục tiêu dưới 12 tháng khi người dùng muốn lãi cao hơn tài khoản thanh toán và chấp nhận dao động rất nhỏ; người có thu nhập không đều cần rút nhanh.$q$, $q$Người cần cam kết lãi suất cố định (nên chọn tiết kiệm kỳ hạn); người cần tăng trưởng dài hạn (lợi suất thấp hơn quỹ cân bằng và cổ phiếu); khi lãi tiết kiệm 6 đến 12 tháng đã bằng hoặc cao hơn lợi suất quỹ, lợi thế giảm.$q$, $q$ ["Quỹ không phải tiền gửi: lợi nhuận không được bảo đảm và không thuộc bảo hiểm tiền gửi.", "Giá trị chứng chỉ quỹ có thể giảm do rủi ro tín dụng của tổ chức phát hành trái phiếu hoặc biến động lãi suất, dù khả năng thấp.", "Lợi nhuận trong quá khứ chỉ mang tính tham khảo; lãi suất tiết kiệm hiện cao khiến chênh lệch với quỹ thu hẹp.", "Có phí bán lại 0,10% nếu rút trong 30 ngày đầu."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBF-BOND$q$, 7, $q$Quỹ Lục Bình Trái phiếu Ổn định$q$, $q$FUND$q$, $q$FUND_BOND$q$, $q$INVESTMENT$q$, 2, 2, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, NULL, 100000, $q$một lần$q$, NULL, $q$lịch sử 5,0 đến 8,0%/năm (không bảo đảm); chỉ bán thứ Ba và thứ Năm; phí bán 2%/1% nếu dưới 12 tháng$q$, $q$khuyến nghị từ 12 tháng, lý tưởng 2 đến 3 năm$q$, $q$Medium. Orders only on two days a week; proceeds in 2 to 3 working days; redemption fee 2% or 1% in the first year, so a sale in under 12 months costs 1 to 2% on top of any market loss.$q$, $q$Quỹ trái phiếu Chính phủ và doanh nghiệp tốt, hợp mục tiêu 1 đến 3 năm; có rủi ro tín dụng, không phải tiền gửi.$q$, $q$Quỹ mở đầu tư vào trái phiếu Chính phủ, trái phiếu doanh nghiệp có chất lượng tín dụng tốt, chứng chỉ tiền gửi và tiền gửi có kỳ hạn. Mục tiêu là lợi nhuận trung hạn cao hơn lãi suất tiết kiệm kỳ hạn dài nhờ danh mục đa dạng, chấp nhận giá trị chứng chỉ quỹ có thể giảm nhẹ trong ngắn hạn. Quỹ phù hợp để nắm giữ từ 1 đến 3 năm.$q$, $q$ ["Historical return (not guaranteed): about 5,0 to 8,0%/năm for bond funds over 1, 3 and 5 years (VCBF-FIF 1 năm 7,40%, 3 năm 7,76%/năm, 5 năm 7,49%/năm tính đến 30/06/2026; 5-year cumulative 20 to 44% across funds). The 2025 calendar-year average was about 5,4%, and some funds earned only 4,6%. A negative month or a drawdown of a few percent is possible in a credit event; the largest drawdowns of weaker credit-heavy funds reached 15 to 20%.", "Recommended holding period: 12 months or more (ideally 2 to 3 years).", "Minimum investment: 100.000 VND; additional purchases from 50.000 VND.", "Fees: management 0,90%/năm; subscription 0%; redemption 2,0% if held under 3 months, 1,0% from 3 to under 12 months, 0% from 12 months; personal income tax on redemption proceeds 0,1%.", "Dealing: twice a week (Tuesday and Thursday); cash in the account 2 to 3 working days after the dealing day (estimate).", "Portfolio guidelines: at most 15% of NAV in a single corporate issuer; investment-grade-equivalent credit policy; no equities."]$q$::jsonb, NULL, $q$Từ đủ 18 tuổi, có tài khoản thanh toán Lục Bình, hoàn thành bảng đánh giá khẩu vị rủi ro. Không yêu cầu thu nhập tối thiểu.$q$, $q$Mục tiêu từ 1 đến 3 năm (đặt cọc, học phí, mua xe) khi người dùng đã có quỹ khẩn cấp riêng và chấp nhận dao động nhỏ; phần ổn định trong danh mục người chọn cân bằng hoặc mạo hiểm; người thận trọng muốn thử một sản phẩm ngoài tiền gửi.$q$, $q$Người cần chắc chắn lấy lại đủ số tiền đã bỏ ra; mục tiêu dưới 12 tháng (phí bán lại và dao động giá có thể xóa phần lãi vượt tiết kiệm); người chưa có quỹ khẩn cấp; người cần đúng thời điểm rút (giao dịch hai ngày một tuần); khi lãi tiết kiệm 12 tháng đã gần bằng lợi suất quỹ (chênh lệch nhỏ).$q$, $q$ ["Không phải tiền gửi; lợi nhuận không được bảo đảm; không thuộc bảo hiểm tiền gửi.", "Rủi ro tín dụng: tổ chức phát hành trái phiếu có thể chậm hoặc không trả được nợ, làm giảm giá trị chứng chỉ quỹ; trái phiếu doanh nghiệp không phải tiền gửi ngân hàng.", "Rủi ro lãi suất: lãi suất thị trường tăng thì giá trái phiếu giảm.", "Phí bán lại 2% hoặc 1% nếu bán trước 12 tháng; chỉ giao dịch vào thứ Ba và thứ Năm.", "Quỹ trái phiếu trong năm 2025 ghi nhận dòng tiền rút ròng khi lãi tiết kiệm tăng; lợi thế so với tiết kiệm không lớn như các năm trước."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBF-BAL$q$, 8, $q$Quỹ Lục Bình Cân bằng$q$, $q$FUND$q$, $q$FUND_BALANCED$q$, $q$INVESTMENT$q$, 3, 3, $q$ ["BALANCED", "GROWTH"]$q$::jsonb, $q$THẬN TRỌNG chỉ như phần nhỏ (tối đa 10 đến 15% tài sản đầu tư), khi mục tiêu trên 5 năm và quỹ khẩn cấp đã đủ.$q$, 100000, $q$một lần$q$, NULL, $q$lịch sử 7 đến 16%/năm, từng giảm 20 đến 28% từ đỉnh (không bảo đảm); phí bán 3/2/0,5/0%$q$, $q$khuyến nghị 3 đến 5 năm trở lên$q$, $q$Medium-high. Sell any working day, cash in 2 to 3 days; cost 0 to 3% by holding period plus any fall in NAV.$q$, $q$Quỹ cổ phiếu (khoảng 50%) và trái phiếu cân bằng; có thể có năm lỗ 10 đến 20%; cho mục tiêu từ 3 đến 5 năm trở lên.$q$, $q$Quỹ mở phân bổ tài sản linh hoạt giữa cổ phiếu niêm yết (khoảng 50%, dao động từ 25% đến 75%) và trái phiếu, tiền gửi, nhằm cân bằng tăng trưởng và ổn định. Giá trị chứng chỉ quỹ có thể giảm trong năm thị trường xấu. Quỹ phù hợp với mục tiêu từ 3 đến 5 năm trở lên.$q$, $q$ ["Historical return (not guaranteed): balanced funds returned 11 to 16%/năm on average over the last 3 years and about 7 to 11%/năm over 5 years (VCBF-TBF: 1 năm 16,31%, 3 năm 15,51%/năm, 5 năm 9,53%/năm, từ khi thành lập 11,53%/năm đến 31/05/2026); in 2025 results ranged from about +12% to +19% for most funds, with one fund at -35,9%. The maximum fall from peak seen in balanced funds over five years was about 20 to 28%.", "Recommended holding period: 3 to 5 years or more.", "Minimum investment: 100.000 VND; additional purchases from 50.000 VND.", "Fees: management 1,50%/năm; subscription 0%; redemption 3,0% (under 1 month), 2,0% (1 to under 12 months), 0,5% (12 to under 24 months), 0% (24 months or more); personal income tax on redemption 0,1%; no performance fee.", "Dealing: every working day; cash 2 to 3 working days after dealing (estimate)."]$q$::jsonb, NULL, $q$Từ đủ 18 tuổi, có tài khoản thanh toán Lục Bình, hoàn thành bảng đánh giá khẩu vị rủi ro với kết quả từ "cân bằng" trở lên (hoặc xác nhận đã hiểu rủi ro nếu chọn "thận trọng"). Không yêu cầu thu nhập tối thiểu.$q$, $q$Mục tiêu từ 3 đến 5 năm trở lên (nhà, hưu trí sớm, học phí con nhiều năm) khi đã có quỹ khẩn cấp và không có nợ lãi cao; người chấp nhận có năm lỗ 10 đến 20% để đổi lấy kỳ vọng sinh lời cao hơn tiền gửi; người muốn một sản phẩm duy nhất đa dạng hóa cổ phiếu và trái phiếu.$q$, $q$Mục tiêu dưới 3 năm; người chưa có quỹ khẩn cấp; người đang có nợ lãi cao (thẻ, vay tín chấp); người sẽ hoảng sợ bán khi giá giảm; người thu nhập không đều chưa có đệm tiền mặt; người chỉ chấp nhận lãi cố định.$q$, $q$ ["Giá trị chứng chỉ quỹ có thể giảm mạnh; trong quá khứ quỹ cân bằng từng giảm khoảng 20 đến 28% từ đỉnh; một quỹ từng giảm 35,9% trong năm 2025.", "Lợi nhuận trong quá khứ không bảo đảm tương lai; kết quả các năm gần đây đang cao hơn mức dài hạn bình thường.", "Phí bán lại giảm dần theo thời gian nắm giữ; bán trong 12 tháng đầu mất 2 đến 3%.", "Không dùng tiền vay để đầu tư vào quỹ; không dùng tiền cần trong 3 năm tới."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBF-IDX30$q$, 9, $q$Quỹ Lục Bình Chỉ số VN30$q$, $q$FUND$q$, $q$FUND_INDEX$q$, $q$INVESTMENT$q$, 4, 4, $q$ ["BALANCED", "GROWTH"]$q$::jsonb, $q$CÂN BẰNG chỉ như phần nhỏ (tối đa 20 đến 25% tài sản đầu tư).$q$, 100000, $q$một lần$q$, NULL, $q$theo chỉ số VN30, từng giảm 35 đến 45% (không bảo đảm); phí bán 1/0,5/0%$q$, $q$khuyến nghị 5 năm trở lên$q$, $q$Medium-high. Daily dealing; proceeds in 2 to 3 working days; the main cost is the market price on the day of sale.$q$, $q$Quỹ mở mô phỏng chỉ số VN30, phí thấp, gần như toàn cổ phiếu nên có thể giảm mạnh; cho mục tiêu từ 5 năm.$q$, $q$Quỹ mở mô phỏng chỉ số VN30 gồm 30 cổ phiếu vốn hóa lớn, thanh khoản cao trên sàn HOSE, với phí quản lý thấp hơn quỹ chủ động. Quỹ đầu tư gần như toàn bộ vào cổ phiếu nên giá trị thay đổi theo thị trường chung và có thể giảm mạnh. Phù hợp để nắm giữ từ 5 năm trở lên và đầu tư định kỳ.$q$, $q$ ["Return: tracks the VN30 index net of costs; no guarantee of any return. Historically, Vietnamese equity-index investments gained about 7%/năm on average over five years to early 2026 (VN-Index +40,4% cumulative), with falls of 35 to 45% peak to trough in bad periods (2022). The ETF market's reference fee is 0,65%/năm.", "Recommended holding period: 5 years or more.", "Minimum investment: 100.000 VND; additional purchases from 50.000 VND.", "Fees: management 0,65%/năm; subscription 0%; redemption 1,0% (under 6 months), 0,5% (6 to under 12 months), 0% (12 months or more); personal income tax on redemption 0,1%.", "Dealing: every working day; cash 2 to 3 working days after dealing (estimate).", "This is an open-ended fund sold through the bank app, not an exchange-traded ETF, so no securities account is needed. (ETFs themselves trade on HOSE through a securities account in lots of 100 and are outside this catalogue.)"]$q$::jsonb, NULL, $q$Từ đủ 18 tuổi, có tài khoản thanh toán Lục Bình, hoàn thành bảng đánh giá khẩu vị rủi ro với kết quả "cân bằng" trở lên và xác nhận đã đọc bản cáo bạch. Không yêu cầu thu nhập tối thiểu.$q$, $q$Mục tiêu từ 5 năm trở lên (hưu trí, quỹ giáo dục dài hạn) khi đã có quỹ khẩn cấp, không có nợ lãi cao; nhà đầu tư muốn chi phí thấp, không muốn chọn quỹ chủ động; đầu tư định kỳ hằng tháng để giảm rủi ro chọn thời điểm.$q$, $q$Mục tiêu dưới 3 đến 5 năm; người thận trọng hoặc không chịu được mức giảm 30 đến 40% tạm thời; người không có quỹ khẩn cấp; người dùng tiền vay; người thu nhập không đều chưa có đệm.$q$, $q$ ["Có thể mất 30 đến 45% giá trị trong giai đoạn thị trường xấu và mất nhiều năm để phục hồi.", "Danh mục tập trung vào một vài ngành (ngân hàng, bất động sản, thép); chỉ số không loại bỏ rủi ro tập trung.", "Không được bảo đảm lợi nhuận; không thuộc bảo hiểm tiền gửi.", "Phí bán lại 1% hoặc 0,5% nếu bán trong 12 tháng đầu."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBF-EQ$q$, 10, $q$Quỹ Lục Bình Cổ phiếu Tăng trưởng$q$, $q$FUND$q$, $q$FUND_EQUITY$q$, $q$INVESTMENT$q$, 5, 5, $q$ ["GROWTH"]$q$::jsonb, $q$Chỉ nên chiếm một phần danh mục đầu tư (thường không quá 30 đến 40% tài sản đầu tư).$q$, 100000, $q$một lần$q$, NULL, $q$lịch sử 8,6 đến 15,4%/năm (5 năm), từng giảm 22 đến 44% (không bảo đảm); phí bán 3/2/1/0%$q$, $q$khuyến nghị 5 năm trở lên$q$, $q$Medium-high on paper (daily dealing); in practice selling in a falling market crystallises the loss, and a sale inside 24 months carries a 1 to 3% fee.$q$, $q$Quỹ cổ phiếu chủ động, tập trung, biến động lớn hơn chỉ số; chỉ cho khẩu vị tăng trưởng, mục tiêu từ 5 năm.$q$, $q$Quỹ mở đầu tư chủ động ít nhất 80% vào cổ phiếu niêm yết, tập trung vào số ít doanh nghiệp để tìm tăng trưởng dài hạn. Biến động của quỹ thường lớn hơn chỉ số thị trường. Chỉ phù hợp với người nắm giữ từ 5 năm trở lên và chịu được việc tài sản giảm mạnh tạm thời.$q$, $q$ ["Historical return (not guaranteed): top actively managed equity funds gained +26 to +33% in 2025 and about +51 to +105% cumulative over 5 years (about 8,6 to 15,4%/năm) for funds with a track record above 5 years, versus +40,4% for the VN-Index. In March 2026 all 82 equity funds fell in a single month. Maximum falls from a peak over five years ranged from 22% to 44%.", "Recommended holding period: 5 years or more.", "Minimum investment: 100.000 VND; additional purchases from 50.000 VND.", "Fees: management 1,95%/năm; subscription 0%; redemption 3,0% (under 1 month), 2,0% (1 to under 12 months), 1,0% (12 to under 24 months), 0% (24 months or more); personal income tax on redemption 0,1%.", "Dealing: every working day; cash 2 to 3 working days after dealing (estimate)."]$q$::jsonb, NULL, $q$Từ đủ 18 tuổi, có tài khoản thanh toán Lục Bình, hoàn thành bảng đánh giá khẩu vị rủi ro với kết quả "mạo hiểm", đã có quỹ khẩn cấp đủ ít nhất 3 tháng chi tiêu (khách tự xác nhận) và xác nhận đã đọc bản cáo bạch.$q$, $q$Mục tiêu từ 5 đến 10 năm trở lên và người có mức chịu rủi ro cao; người đã có quỹ khẩn cấp, bảo hiểm sức khỏe và không có nợ lãi cao; chỉ nên chiếm một phần của danh mục đầu tư (thường không quá 30 đến 40% tài sản đầu tư).$q$, $q$Mục tiêu dưới 5 năm; người thận trọng hoặc cân bằng; người chưa có quỹ khẩn cấp; người đang vay nợ lãi cao; người thu nhập không đều; người dùng tiền vay hoặc tiền đã dành cho mục tiêu gần.$q$, $q$ ["Có thể mất 30 đến 45% giá trị trong giai đoạn thị trường xấu và cần nhiều năm để phục hồi.", "Danh mục tập trung nên biến động có thể lớn hơn chỉ số VN-Index; quỹ có kết quả khác nhau rất xa, ví dụ lợi nhuận 1 năm từ âm đến trên 30%.", "Lợi nhuận quá khứ không bảo đảm tương lai; nhiều năm gần đây thị trường tăng mạnh, không nên xem là mức bình thường.", "Không dùng tiền vay; không dùng tiền cần trong 5 năm tới."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-SIP$q$, 11, $q$Chương trình Đầu tư Định kỳ Lục Bình (SIP)$q$, $q$FUND$q$, $q$INVESTMENT_PROGRAM$q$, $q$INVESTMENT$q$, 2, 5, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, $q$Mức rủi ro bằng mức của quỹ được chọn (LBF-LIQ 2, LBF-BOND 2, LBF-BAL 3, LBF-IDX30 4, LBF-EQ 5); hồ sơ rủi ro quyết định quỹ nào được chọn.$q$, 100000, $q$mỗi tháng$q$, NULL, $q$phí mua 0%; tạm dừng bất kỳ lúc nào; lợi nhuận và rủi ro theo quỹ chọn$q$, $q$theo quỹ chọn$q$, $q$As each fund; the SIP can be paused or stopped at any time at no cost.$q$, $q$Tự động trích hằng tháng từ 100.000 đồng để mua quỹ đã chọn; không bảo đảm lãi, không hạn chế lỗ.$q$, $q$Chương trình tự động trích tiền từ tài khoản thanh toán hằng tháng để mua chứng chỉ quỹ đã chọn, từ 100.000 đồng mỗi tháng. Đầu tư đều đặn giúp giảm ảnh hưởng của việc chọn sai thời điểm và tạo kỷ luật tiết kiệm. Khách hàng có thể tạm dừng, đổi số tiền hoặc chấm dứt bất kỳ lúc nào. Chương trình không bảo đảm lợi nhuận hay hạn chế lỗ.$q$, $q$ ["Minimum 100.000 VND per month; maximum 100.000.000 VND per month; debit date chosen between day 1 and day 28.", "Eligible funds: LBF-LIQ, LBF-BOND, LBF-BAL, LBF-IDX30, LBF-EQ (each fund's own redemption fee schedule still applies, counted from each monthly purchase).", "Subscription fee: 0% (waived for all SIP purchases); no program fee.", "If a debit fails (insufficient balance), the order is skipped for that month; two consecutive failures suspend the program.", "Tax on redemption proceeds 0,1% as for each fund."]$q$::jsonb, NULL, $q$Từ đủ 18 tuổi, có tài khoản thanh toán Lục Bình, đã hoàn thành bảng đánh giá khẩu vị rủi ro phù hợp với quỹ chọn.$q$, $q$Người có lương đều đặn và đã có quỹ khẩn cấp, muốn xây tài sản dài hạn cho mục tiêu từ 3 đến 5 năm trở lên; người mới đầu tư; người muốn biến phần dư hằng tháng thành khoản đầu tư tự động.$q$, $q$Người thu nhập rất bấp bênh (khoản trích cố định dễ bị lỡ); người chưa có quỹ khẩn cấp; người có nợ lãi cao đang trả; mục tiêu dưới 12 tháng.$q$, $q$ ["Đầu tư định kỳ không loại bỏ rủi ro lỗ; nếu thị trường giảm kéo dài, giá trị vẫn có thể thấp hơn số tiền đã bỏ ra.", "Mỗi lần mua có thời gian nắm giữ riêng nên phí bán lại tính theo từng lần mua.", "Đặt mức trích hợp lý so với dòng tiền; trích quá cao có thể buộc phải rút quỹ khẩn cấp hoặc vay."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-LN-UNSEC$q$, 12, $q$Vay Tiêu dùng Tín chấp Lục Bình$q$, $q$LOAN$q$, $q$LOAN_UNSECURED$q$, $q$DEBT$q$, 4, 4, $q$ []$q$::jsonb, $q$Phương án cuối cùng: chỉ cho chi bắt buộc khi đã hết quỹ khẩn cấp hoặc để gộp nợ lãi cao hơn; không bao giờ để đầu tư.$q$, 10000000, $q$một lần$q$, 8000000, $q$14,5 đến 19,5%/năm dư nợ giảm dần (tham chiếu 16,0%); 12 đến 60 tháng; tối đa 500 triệu$q$, $q$12 đến 60 tháng$q$, $q$Not applicable (a liability). Prepayment is allowed with the fee above.$q$, $q$Vay không tài sản bảo đảm, lãi cao gấp nhiều lần tiết kiệm; phí trả nợ trước hạn 3% năm đầu.$q$, $q$Khoản vay không cần tài sản bảo đảm cho nhu cầu tiêu dùng như sửa nhà, y tế, học tập, trả nợ khoản vay lãi cao hơn. Lãi suất tính trên dư nợ giảm dần, trả góp gốc và lãi hằng tháng, kỳ hạn 12 đến 60 tháng. Hạn mức và lãi suất phụ thuộc thu nhập, lịch sử tín dụng và nghĩa vụ trả nợ hiện có.$q$, $q$ ["Interest: from 14,5% to 19,5%/năm on the reducing balance, depending on credit score and employer category (salary paid through the bank earns the low end). Reference rate for a typical salaried customer: 16,0%/năm.", "Tenor: 12 to 60 months.", "Maximum amount: the lower of 500.000.000 VND and 12 times average net monthly income (the multiple is our assumption; the bank's other limits also apply).", "Minimum amount: 10.000.000 VND.", "Fees: no arrangement fee; early repayment fee 3% of the prepaid principal in year 1, 2% in year 2, 1% from year 3 (free in the last 6 months); late-payment interest on overdue principal = 150% of the contractual rate; optional loan-protection insurance may be offered but cannot be a condition of the loan.", "Example: 100.000.000 VND, 36 months, 16%/năm: monthly payment about 3.516.000 VND, total interest about 26,6 million VND."]$q$::jsonb, NULL, $q$Thu nhập ròng tối thiểu 8.000.000 VND/tháng (có sao kê lương hoặc hợp đồng lao động); tuổi từ 22 đến 60 khi vay (kỳ hạn kết thúc trước 65 tuổi). Làm việc tại nơi hiện tại tối thiểu 6 tháng. Tổng nghĩa vụ trả nợ hằng tháng (kể cả khoản vay mới) không quá 50% thu nhập; không có nợ nhóm 2 trở lên trong 12 tháng gần nhất trên hồ sơ tín dụng CIC.$q$, $q$Cần chi cố định bắt buộc (y tế, sửa nhà khẩn cấp) khi đã dùng hết quỹ khẩn cấp; gộp các khoản nợ lãi cao hơn (thẻ tín dụng 27%, tài chính tiêu dùng 30% đến 45%) thành một khoản lãi thấp hơn, khi có kế hoạch không phát sinh nợ mới.$q$, $q$Không dùng để đầu tư (quỹ, chứng khoán, tiền mã hóa), mua sắm không thiết yếu hoặc du lịch; không phù hợp nếu tổng nghĩa vụ trả nợ sau khi vay vượt khoảng 40% thu nhập; người thu nhập không đều; người đã có hai khoản vay tiêu dùng trở lên.$q$, $q$ ["Lãi suất cao hơn nhiều lần lãi tiết kiệm (14,5 đến 19,5% so với 6,4%); vay để đầu tư gần như chắc chắn thua về chi phí.", "Tổng tiền lãi trả trong cả kỳ hạn đáng kể; ví dụ vay 100 triệu đồng 36 tháng trả khoảng 26,6 triệu đồng lãi.", "Có phí trả nợ trước hạn 3% trong năm đầu.", "Trả chậm bị tính lãi quá hạn 150% lãi suất trong hạn và ghi nhận nợ xấu trên CIC, ảnh hưởng đến khoản vay mua nhà sau này.", "Ngân hàng không được bắt buộc mua bảo hiểm để được vay; có thể từ chối bảo hiểm nhân thọ đi kèm."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-LN-HOME$q$, 13, $q$Vay Mua nhà Lục Bình$q$, $q$LOAN$q$, $q$LOAN_MORTGAGE$q$, $q$DEBT$q$, 3, 3, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, $q$Chỉ khi qua kiểm tra khả năng trả nợ (tổng nghĩa vụ trả nợ tối đa 40% thu nhập, thử lãi thả nổi cộng 2 điểm) và vốn tự có từ 25%.$q$, NULL, NULL, 15000000, $q$9,6%/năm cố định 12 tháng (10,2% nếu 24 tháng), sau đó 11,0% thả nổi; vay tối đa 75% giá trị, 30 năm$q$, $q$5 đến 30 năm$q$, $q$Not applicable (a liability). Early repayment is possible with fees in the first years; refinancing at another bank is possible under SBV rules.$q$, $q$Vay dài hạn có thế chấp chính căn nhà; lãi thả nổi sau ưu đãi nên khoản trả hằng tháng có thể tăng 20 đến 30%.$q$, $q$Khoản vay dài hạn có tài sản bảo đảm là chính căn nhà hoặc căn hộ mua, để mua, xây hoặc sửa nhà ở. Lãi suất cố định ưu đãi trong 12 hoặc 24 tháng đầu, sau đó thả nổi theo công thức lãi suất tiền gửi cộng biên độ cố định, nên khoản trả hằng tháng có thể tăng. Có thể vay đến 75% giá trị tài sản bảo đảm, kỳ hạn tối đa 30 năm.$q$, $q$ ["Preferential fixed rate: 9,6%/năm for the first 12 months; 10,2%/năm for the first 24 months (customer chooses one package).", "Floating rate after the preferential period: our 13-month counter deposit rate (currently 6,20%/năm) + margin 4,8% = 11,0%/năm today; reset every 3 months; no cap. In recent market surveys floating rates ran from 11% to 16%.", "Maximum loan-to-value: 75% of the collateral valuation (80% for projects partnered with the bank; the customer must fund the remainder).", "Tenor: 5 to 30 years. Principal grace up to 12 months for off-plan purchases.", "Fees: appraisal fee per tariff (about 0,05 to 0,10% of value, estimate); early repayment fee on prepaid principal: 3% in years 1 and 2, 2% in year 3, 1% in year 4, 0% from year 5. Part-prepayment of at least 5% of outstanding principal allowed.", "Illustration (not an offer): 2.000.000.000 VND, 20 years, 9,6% for 12 months: monthly payment about 18,77 million VND; after the preferential period at 11,0% about 20,58 million; if floating rate reaches 13% about 23,29 million (calculated on the outstanding balance after 12 months)."]$q$::jsonb, NULL, $q$Thu nhập ròng tối thiểu 15.000.000 VND/tháng; tuổi từ 22 đến 60 khi vay, đáo hạn khoản vay không quá 65 tuổi (ước tính chính sách). Tổng nghĩa vụ trả nợ hằng tháng (kể cả khoản vay mới) không quá 50% thu nhập ròng; hồ sơ CIC không có nợ nhóm 2 trở lên trong 24 tháng. Tài sản bảo đảm có giấy chứng nhận hợp pháp; khách hàng có vốn tự có tối thiểu 25% giá trị căn nhà.$q$, $q$Người có thu nhập ổn định, đã có vốn tự có tối thiểu 25 đến 30% giá trị nhà và quỹ khẩn cấp 6 tháng sau khi trả tiền đặt cọc; người có thể chịu khoản trả hằng tháng tăng 20 đến 30% sau thời gian ưu đãi; người ở lâu dài, không có kế hoạch bán trong 3 năm.$q$, $q$Người thu nhập không đều hoặc dưới ngưỡng; người dự định bán hoặc trả nợ trước trong 3 năm đầu (phí trả nợ trước hạn); người đã có khoản trả nợ khác khiến tổng trên 40% thu nhập; người muốn "đầu cơ" cho thuê mà không có dòng tiền dự phòng; người không có quỹ khẩn cấp sau khi trả vốn tự có.$q$, $q$ ["Lãi suất thả nổi sau thời gian ưu đãi cao hơn lãi suất ưu đãi (hiện 11,0% so với 9,6%) và có thể tăng thêm khi lãi suất tiền gửi tăng; nên tính khả năng trả nợ với lãi suất cao hơn 2 điểm phần trăm.", "Ví dụ khoản vay 2 tỷ đồng trong 20 năm: số trả hằng tháng có thể tăng từ khoảng 18,8 triệu lên 20,6 đến 23,3 triệu đồng sau 12 tháng.", "Phí trả nợ trước hạn 3% trong 2 năm đầu, giảm dần; hỏi rõ số cụ thể trước khi ký.", "Tài sản bị thế chấp; chậm trả kéo dài có thể bị xử lý tài sản.", "Bảo hiểm nhà hoặc bảo hiểm khoản vay đi kèm là lựa chọn, không phải điều kiện bắt buộc."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-LN-AUTO$q$, 14, $q$Vay Mua ô tô Lục Bình$q$, $q$LOAN$q$, $q$LOAN_AUTO$q$, $q$DEBT$q$, 3, 3, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, $q$Chỉ khi qua kiểm tra khả năng trả nợ; tổng chi phí xe hằng tháng nên dưới khoảng 15 đến 20% thu nhập.$q$, NULL, NULL, 12000000, $q$8,5%/năm cố định 12 tháng, sau đó 11,0% thả nổi; vay tối đa 80% giá xe mới, 8 năm$q$, $q$tối đa 8 năm (96 tháng)$q$, $q$Not applicable (a liability). Prepayment possible with fees.$q$, $q$Vay mua ô tô thế chấp chính chiếc xe; xe mất giá nhanh, bắt buộc bảo hiểm vật chất xe.$q$, $q$Khoản vay mua ô tô dưới 9 chỗ hoặc xe bán tải, tài sản bảo đảm là chính chiếc xe mua. Lãi suất cố định ưu đãi trong 12 tháng đầu, sau đó thả nổi theo lãi suất tiết kiệm cộng biên độ. Cho vay đến 80% giá xe mới, kỳ hạn tối đa 8 năm.$q$, $q$ ["Preferential rate: 8,5%/năm cố định 12 tháng đầu; after that floating = 13-month counter deposit rate (6,20%) + margin 4,8% = 11,0%/năm today, reset every 3 months.", "Loan-to-value: up to 80% of the contract price for new cars; up to 70% of valuation for used cars (under 5 years old).", "Tenor: up to 8 years (96 months) for new cars; up to 5 years for used cars.", "Fees: early repayment 3% (year 1), 2% (year 2), 1% (year 3), then free; mandatory comprehensive vehicle insurance (vật chất xe) for the whole loan, premium about 1,3 to 1,6% of the car value per year (estimate); registration and car-lien fees paid by the customer.", "Illustration: 600.000.000 VND, 7 years, 8,5% year 1: monthly payment about 9,50 million VND; about 10,17 million VND after the rate moves to 11,0%."]$q$::jsonb, NULL, $q$Thu nhập ròng tối thiểu 12.000.000 VND/tháng; tuổi từ 22 đến 60 khi vay (kỳ hạn kết thúc trước 65 tuổi). Vốn tự có tối thiểu 20% giá xe; tổng nghĩa vụ trả nợ hằng tháng không quá 50% thu nhập; không có nợ nhóm 2 trở lên trong 12 tháng gần nhất.$q$, $q$Người có thu nhập ổn định, xe phục vụ đi làm hoặc kinh doanh, đã có vốn tự có 20% và quỹ khẩn cấp; tổng chi phí xe hằng tháng (trả nợ, xăng, bảo hiểm, gửi xe, bảo dưỡng) dưới khoảng 15 đến 20% thu nhập.$q$, $q$Người thu nhập không đều; người chưa có quỹ khẩn cấp hoặc đang có nợ lãi cao; người mua xe chỉ vì ưu đãi lãi suất; người đang để dành cho nhà ở.$q$, $q$ ["Xe mất giá nhanh trong vài năm đầu nhưng khoản nợ vẫn giảm chậm.", "Sau 12 tháng lãi suất thả nổi (hiện 11,0%) cao hơn lãi suất ưu đãi (8,5%).", "Bắt buộc mua bảo hiểm vật chất xe trong thời gian vay; chi phí này, cùng phí trước bạ, đăng ký và bảo dưỡng, cần tính vào tổng chi phí.", "Phí trả nợ trước hạn 3% trong năm đầu."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-OD$q$, 15, $q$Thấu chi Tài khoản Lục Bình$q$, $q$LOAN$q$, $q$OVERDRAFT$q$, $q$DEBT$q$, 3, 3, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, $q$Chỉ làm cầu nối vài ngày đến vài tuần trước ngày nhận lương, không dùng để chi tiêu thường xuyên.$q$, 5000000, $q$hạn mức tối thiểu$q$, 7000000, $q$16,0%/năm trên số dư thực dùng; hạn mức 5 đến 50 triệu$q$, $q$12 tháng, gia hạn$q$, $q$Not applicable (a liability). Repay any time without fee.$q$, $q$Chi vượt số dư tài khoản nhận lương, lãi tính theo ngày thực dùng; rẻ hơn rút tiền mặt thẻ nhưng vẫn đắt.$q$, $q$Hạn mức cho phép chi tiêu vượt số dư trên tài khoản thanh toán nhận lương, lãi chỉ tính trên số tiền thực dùng và số ngày thực dùng. Hạn mức xem xét lại hằng năm. Phù hợp để xử lý thiếu hụt tạm thời vài ngày đến vài tuần trước ngày nhận lương, không dùng để chi tiêu thường xuyên.$q$, $q$ ["Interest: 16,0%/năm on the daily overdrawn balance (daily interest = balance x 16% / 365 x days); interest charged monthly.", "Limit: up to 2 times the average net salary credited to the account over the last 3 months, maximum 50.000.000 VND, minimum 5.000.000 VND.", "Term: 12 months, renewable subject to review; each drawing should be repaid within 30 days (no fixed maturity per drawing, but the limit is reviewed if overdrawn for 60 consecutive days).", "Fees: annual limit fee 0%; no fee per drawing; overdue interest 150% of the contractual rate on amounts above the limit or not repaid at term.", "Example: overdraw 10.000.000 VND for 45 days at 16%: interest about 197.000 VND."]$q$::jsonb, NULL, $q$Nhận lương qua tài khoản Lục Bình tối thiểu 3 tháng liên tục, lương ròng tối thiểu 7.000.000 VND/tháng; tuổi 20 đến 55; hợp đồng lao động từ 12 tháng; không có nợ nhóm 2 trở lên trong 12 tháng gần nhất.$q$, $q$Người nhận lương đều, thỉnh thoảng thiếu hụt vài ngày; người đã có quỹ khẩn cấp nhưng cần cầu nối ngắn; thay cho việc rút tiền mặt thẻ tín dụng (chi phí cao hơn).$q$, $q$Người thu nhập không đều; người đang phụ thuộc vào thấu chi mỗi tháng (dấu hiệu chi tiêu vượt thu nhập); người đã có nợ tiêu dùng khác; người cần số tiền lớn dài hạn (nên cân nhắc vay tín chấp trả góp).$q$, $q$ ["Lãi suất 16%/năm cao hơn nhiều so với lãi tiết kiệm; để thấu chi dài ngày làm chi phí tăng nhanh.", "Hạn mức bị xem xét lại nếu thấu chi liên tục quá 60 ngày.", "Lãi tính theo ngày thực dùng; trả đúng hạn để tránh lãi quá hạn 150%.", "Ghi nhận trên hồ sơ tín dụng CIC như một khoản vay."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-CC-CASHBACK$q$, 16, $q$Thẻ tín dụng Lục Bình Hoàn tiền$q$, $q$CARD$q$, $q$CREDIT_CARD$q$, $q$DEBT$q$, 3, 4, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, $q$Chỉ cho người thanh toán đủ dư nợ mỗi tháng; mức rủi ro 4 khi để dư nợ.$q$, NULL, NULL, 8000000, $q$27%/năm nếu không trả đủ; miễn lãi đến 45 ngày; phí thường niên 399.000; hoàn tiền 1 đến 5% (tối đa 400.000/tháng)$q$, $q$thẻ không kỳ hạn; trả góp 3 đến 12 tháng$q$, $q$Not applicable (a liability); prepay or pay in full any time.$q$, $q$Thẻ tín dụng hoàn tiền, trả góp 0% tại đối tác; chỉ có lợi nếu trả đủ mỗi tháng, nếu không lãi 27%/năm.$q$, $q$Thẻ tín dụng quốc tế dùng thanh toán trong nước và nước ngoài, miễn lãi tối đa 45 ngày cho giao dịch mua sắm khi thanh toán đủ dư nợ sao kê, và hoàn tiền cho chi tiêu ăn uống, mua sắm trực tuyến, siêu thị. Có tính năng trả góp 0% tại đối tác và chuyển đổi giao dịch đã chi tiêu sang trả góp hằng tháng. Chỉ có lợi khi khách hàng trả đủ mỗi tháng.$q$, $q$ ["Annual fee: 399.000 VND per year; first year free if the customer spends at least 1.000.000 VND within 45 days of activation; from year 2 waived if annual spending reaches 60.000.000 VND.", "Interest: 27,0%/năm on the outstanding balance if the statement is not paid in full (interest charged from the transaction date on all purchases that month once the interest-free condition is lost).", "Interest-free period: up to 45 days (30-day statement cycle + 15-day payment period) for purchases, only if the previous statement balance was paid in full; none for cash advances.", "Minimum payment: 5% of the statement balance (minimum 100.000 VND) by the due date.", "Fees: late payment 4% of the unpaid minimum amount (minimum 100.000 VND); cash advance 4% of the amount (minimum 50.000 VND) with interest from the day of withdrawal; foreign-currency conversion 2,5%; over-limit 100.000 VND; replacement card 100.000 VND.", "Cashback: 5% on dining, online shopping and supermarkets, 1% on other domestic spending, only on monthly spending of at least 3.000.000 VND; maximum cashback 400.000 VND per month in total.", "Credit limit: 2 to 3 times net monthly income; first card up to 100.000.000 VND.", "Instalment (included): 0% interest instalments at partner merchants for 3, 6, 9 or 12 months (no fee when the merchant bears the cost). Conversion of past purchases (each at least 3.000.000 VND, within 60 days of the transaction): conversion fee 0,60% per month on the original converted amount (flat), tenor 3, 6, 9 or 12 months, which is about 13 to 14% per year effective; cancelling an instalment costs 2% of the remaining principal (minimum 100.000 VND). Instalments reduce the available limit.", "Illustration: carrying a 10.000.000 VND balance one month at 27% costs about 225.000 VND in interest on top of fees."]$q$::jsonb, NULL, $q$Từ 20 đến 60 tuổi, thu nhập ròng tối thiểu 8.000.000 VND/tháng (có sao kê lương hoặc hợp đồng lao động), không có nợ nhóm 2 trở lên trong 12 tháng gần nhất trên hồ sơ CIC. Hạn mức dựa trên thu nhập và lịch sử tín dụng.$q$, $q$Người có thu nhập đều, luôn thanh toán đủ dư nợ mỗi kỳ sao kê, chi tiêu từ 3 triệu đồng mỗi tháng để hưởng hoàn tiền; người mua hàng giá trị lớn thiết yếu cần chia nhỏ trong 3 đến 12 tháng với chi phí thấp.$q$, $q$Người hay quên thanh toán hoặc chỉ trả tối thiểu; người đang có nợ lãi cao (thẻ khác, vay tín chấp); người thu nhập không đều; người dễ chi tiêu quá tay; người định rút tiền mặt qua thẻ.$q$, $q$ ["Nếu không thanh toán đủ dư nợ sao kê, mất ưu đãi miễn lãi và bị tính lãi 27%/năm từ ngày giao dịch (khoảng 225.000 đồng một tháng cho 10 triệu đồng).", "Chỉ trả khoản tối thiểu (5%) làm dư nợ giảm rất chậm và lãi chồng lên; thanh toán trễ bị phạt 4% khoản tối thiểu chưa trả (tối thiểu 100.000 đồng) và ghi nhận nợ xấu trên CIC.", "Rút tiền mặt mất phí 4% (tối thiểu 50.000 đồng) và tính lãi ngay, không có thời gian miễn lãi.", "Trả góp chuyển đổi mất phí 0,60% mỗi tháng (khoảng 13 đến 14% năm), tính cả khi trả hết sớm; hủy trước hạn mất 2% dư nợ gốc còn lại.", "Hoàn tiền chỉ áp dụng khi chi tiêu từ 3 triệu đồng mỗi tháng và bị giới hạn 400.000 đồng; không nên chi tiêu thêm chỉ để lấy hoàn tiền."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-INS-HEALTH$q$, 17, $q$Bảo hiểm Sức khỏe An Khuê$q$, $q$INSURANCE$q$, $q$INSURANCE_HEALTH$q$, $q$PROTECTION$q$, 1, 1, $q$ ["CONSERVATIVE", "BALANCED", "GROWTH"]$q$::jsonb, NULL, NULL, NULL, NULL, $q$phí từ khoảng 2,8 triệu/năm (tuổi 30, gói Cơ bản); hạn mức nội trú 100 triệu đến 1 tỷ/năm$q$, $q$1 năm, tái tục$q$, $q$Not a savings product: no cash value and no refund of unused premium. Cancelling mid-term refunds a short-period portion only (typical).$q$, $q$Bảo hiểm sức khỏe của An Khuê: chi trả nằm viện, phẫu thuật; không tích lũy, không hoàn phí nếu không bồi thường.$q$, $q$Bảo hiểm sức khỏe tái tục hằng năm do Công ty Bảo hiểm An Khuê cung cấp, chi trả chi phí nằm viện, phẫu thuật và (tùy gói) điều trị ngoại trú, theo hạn mức hằng năm. Đây là sản phẩm bảo vệ: không có giá trị tích lũy, không hoàn phí nếu không có yêu cầu bồi thường. Lục Bình chỉ là đơn vị phân phối, việc bán không được gắn với khoản vay hoặc tiền gửi.$q$, $q$ ["Ba gói, hạn mức quyền lợi và phí ước tính mỗi năm cho người lớn (VND):", "Gói: Cơ bản; Hạn mức nội trú/năm: 100.000.000; Ngoại trú: không; Phí/năm (tuổi 30): khoảng 2.800.000; Phí/năm (tuổi 45): khoảng 4.200.000", "Gói: Nâng cao; Hạn mức nội trú/năm: 300.000.000; Ngoại trú: có, tối đa 10.000.000; Phí/năm (tuổi 30): khoảng 6.500.000; Phí/năm (tuổi 45): khoảng 9.800.000", "Gói: Toàn diện; Hạn mức nội trú/năm: 1.000.000.000; Ngoại trú: có, tối đa 30.000.000, kèm nha khoa cơ bản; Phí/năm (tuổi 30): khoảng 14.000.000; Phí/năm (tuổi 45): khoảng 21.000.000", "Waiting period: 30 days for illness; 12 months for pre-existing conditions (excluded or after a waiting period depending on declared history); accident cover starts at once.", "Policy term: 1 year, renewable; premiums can rise with age band and claims experience; the insurer may decline renewal only under the policy conditions.", "Payment: annual or in instalments (surcharge about 5% for monthly payment).", "Premium relative to income (estimate): the Cơ bản plan at age 30 is about 1,6% of annual income for someone earning 15.000.000 VND/month; Toàn diện is about 7,8% of annual income at the same income.", "Cooling-off period: for contracts over 1 year only (21 days by law); a 1-year contract is outside this right unless the insurer grants it."]$q$::jsonb, NULL, $q$Từ 1 tháng tuổi đến 60 tuổi khi tham gia (tái tục đến 65 tuổi); khai báo tình trạng sức khỏe trung thực; không yêu cầu thu nhập tối thiểu nhưng phí gói Nâng cao và Toàn diện nên được cân đối theo thu nhập.$q$, $q$Người có thu nhập mà một ca nằm viện hoặc phẫu thuật lớn có thể làm cạn quỹ khẩn cấp; người chỉ có bảo hiểm y tế nhà nước (BHYT) và muốn bổ sung phần chi phí ngoài danh mục; người có gia đình phụ thuộc vào thu nhập của mình; người làm tự do không có bảo hiểm công ty.$q$, $q$Người đã được công ty đóng bảo hiểm sức khỏe đầy đủ (không cần mua trùng); người coi bảo hiểm là cách để dành tiền; người không đủ ngân sách đóng phí liên tục nhiều năm (hợp đồng bị hủy làm mất quyền lợi); người đang có bệnh nền nặng cần kiểm tra điều khoản loại trừ.$q$, $q$ ["Phí không được hoàn lại nếu không có bồi thường; đây là sản phẩm bảo vệ, không phải tiết kiệm.", "Phí tăng theo tuổi và có thể tăng theo kinh nghiệm bồi thường khi tái tục.", "Có thời gian chờ và các bệnh có sẵn có thể bị loại trừ; khai báo sai có thể bị từ chối bồi thường.", "Ngân hàng không được bắt buộc mua bảo hiểm để được vay hoặc nhận ưu đãi; nếu bị yêu cầu, khách hàng có quyền từ chối và khiếu nại.", "Nên so sánh với gói bảo hiểm của công ty và với các nhà bảo hiểm khác trước khi mua."]$q$::jsonb, DATE '2026-11-13', TRUE),
($q$LBB-INS-LIFE$q$, 18, $q$Bảo hiểm Nhân thọ Tích lũy An Khuê$q$, $q$INSURANCE$q$, $q$INSURANCE_LIFE_SAVINGS$q$, $q$PROTECTION$q$, 3, 3, $q$ ["CONSERVATIVE", "BALANCED"]$q$::jsonb, $q$Chỉ khi có nhu cầu bảo vệ thực sự (người phụ thuộc, khoản vay lớn) và dòng tiền ổn định, sau khi đã có bảo hiểm sức khỏe; không khuyến nghị làm sản phẩm tiết kiệm hay đầu tư.$q$, 12000000, $q$mỗi năm (phí tối thiểu)$q$, 15000000, $q$lãi đảm bảo 2,0%/năm, công bố khoảng 4,8% (không đảm bảo); cam kết 15 đến 20 năm; 21 ngày cân nhắc$q$, $q$đóng phí 10, 15 hoặc 20 năm$q$, $q$Low. Cash surrender is possible but usually returns less than the premiums paid, particularly in the first 5 years (and nothing in the first two years); a policy loan is a way to access part of the value without cancelling.$q$, $q$Bảo hiểm nhân thọ liên kết chung, bảo vệ có kèm tích lũy; hủy sớm thường mất phần lớn phí, không phải tiền gửi.$q$, $q$Bảo hiểm nhân thọ liên kết chung của Công ty Bảo hiểm An Khuê: phần phí bảo hiểm sau khi trừ các khoản phí được tích lũy vào tài khoản hợp đồng và hưởng lãi suất công bố hằng tháng, có mức tối thiểu cam kết. Hợp đồng bảo vệ rủi ro tử vong và thương tật toàn bộ vĩnh viễn và là cam kết dài hạn 15 đến 20 năm. Đây là sản phẩm bảo vệ có kèm tích lũy, không phải khoản tiền gửi tiết kiệm.$q$, $q$ ["Minimum regular premium: 12.000.000 VND per year (1.000.000 VND per month). Premium payment term 10, 15 or 20 years; policy term to age 75 or at least 20 years.", "Minimum sum assured: 10 times annual basic premium (more at older ages).", "Account value interest: guaranteed minimum 2,0%/năm; declared rate currently about 4,8%/năm (not guaranteed; declared monthly by the insurer).", "Charges: initial charges deducted from premiums are high in the first years (most of the first-year premium is not credited to the account); plus cost-of-insurance and administration charges monthly.", "Surrender value: typically zero in the first two years (market pattern), and below total premiums paid for several years after; the insurer's own benefit illustration for the actual contract must be shown to the customer.", "Cooling-off period: 21 days from receiving the contract (Law on Insurance Business 08/2022/QH15, Art. 35): the customer can cancel and receive a refund of premium paid minus medical-exam costs (as described by the law).", "Policy loan: up to 80% of the surrender value (estimate), interest per policy terms.", "Premium relative to income (estimate): 12.000.000 VND per year is 6,7% of annual income at 15.000.000 VND/month and 10,0% at 10.000.000 VND/month."]$q$::jsonb, NULL, $q$Từ 18 đến 55 tuổi khi tham gia; thu nhập ròng tối thiểu 15.000.000 VND/tháng (để phí không vượt khoảng 7% thu nhập); khai báo sức khỏe trung thực; không áp dụng cho khách hàng đang vay mà hợp đồng bảo hiểm bị đặt làm điều kiện cho khoản vay.$q$, $q$Người trụ cột có gia đình hoặc nợ lớn (ví dụ vay mua nhà) cần bảo vệ thu nhập; người có thu nhập đều, đã có quỹ khẩn cấp, đã có bảo hiểm sức khỏe, và chắc chắn đóng phí liên tục 15 đến 20 năm; phần tích lũy chỉ là phụ trợ.$q$, $q$Không dùng để tiết kiệm cho mục tiêu dưới 10 năm; người cần tiền trong 5 năm; người thu nhập không đều hoặc chưa có quỹ khẩn cấp; người độc thân không phụ thuộc; người đang vay lãi cao; người mua vì tin đây là "tiền gửi lãi cao" hoặc vì ngân hàng gợi ý khi vay.$q$, $q$ ["Đây không phải tiền gửi tiết kiệm và không thuộc bảo hiểm tiền gửi; lãi suất công bố không được bảo đảm, chỉ có mức tối thiểu cam kết 2,0%/năm.", "Hủy sớm thường mất phần lớn hoặc toàn bộ phí đã đóng: giá trị hoàn lại thường bằng 0 trong 2 năm đầu và thấp hơn phí đã đóng trong nhiều năm sau đó.", "Cam kết đóng phí 15 đến 20 năm; bỏ đóng phí làm hợp đồng mất hiệu lực.", "Có 21 ngày cân nhắc để hủy hợp đồng và nhận lại phí đã đóng (trừ chi phí khám sức khỏe).", "Cảnh báo của thị trường bảo hiểm qua ngân hàng: trong các năm 2023 đến 2024 xuất hiện nhiều phản ánh khách hàng bị tư vấn mua bảo hiểm như một khoản tiết kiệm lãi cao hoặc bị gắn với khoản vay. Ngân hàng không được ép mua bảo hiểm hoặc coi bảo hiểm là điều kiện của sản phẩm ngân hàng (Luật Các tổ chức tín dụng 2024); luôn đọc kỹ bảng minh họa quyền lợi và điều khoản."]$q$::jsonb, DATE '2026-11-13', TRUE);
